# Brand baseline scores (1-5 scale), directional estimates based on well-known
# reliability/reputation trends (Consumer Reports / JD Power style consensus).
BRAND_RELIABILITY = {
    "Toyota": 4.8, "Lexus": 4.8, "Mazda": 4.5, "Honda": 4.3, "Acura": 4.2,
    "Subaru": 4.0, "Kia": 3.9, "Hyundai": 3.9, "Genesis": 4.2, "Buick": 3.9,
    "Ford": 3.4, "Chevrolet": 3.4, "GMC": 3.5, "Nissan": 3.4, "Volkswagen": 3.3,
    "Ram": 2.9, "Jeep": 2.8, "Dodge": 2.9, "Chrysler": 2.8, "Cadillac": 3.2,
    "Land Rover": 2.6, "BMW": 3.4, "Mercedes-Benz": 3.2, "Audi": 3.3,
    "Tesla": 3.4, "Rivian": 3.2, "Polestar": 3.1, "Porsche": 4.0,
    "Mitsubishi": 3.6, "Mini": 3.0,
}

BRAND_SITE = {
    "Toyota": "toyota.com", "Lexus": "lexus.com", "Mazda": "mazda.com", "Honda": "honda.com",
    "Acura": "acura.com", "Subaru": "subaru.com", "Kia": "kia.com", "Hyundai": "hyundaiusa.com",
    "Genesis": "genesis.com", "Buick": "buick.com", "Ford": "ford.com", "Chevrolet": "chevrolet.com",
    "GMC": "gmc.com", "Nissan": "nissanusa.com", "Volkswagen": "vw.com", "Ram": "ramtrucks.com",
    "Jeep": "jeep.com", "Dodge": "dodge.com", "Chrysler": "chrysler.com", "Cadillac": "cadillac.com",
    "Land Rover": "landroverusa.com", "BMW": "bmwusa.com", "Mercedes-Benz": "mbusa.com",
    "Audi": "audiusa.com", "Tesla": "tesla.com", "Rivian": "rivian.com", "Polestar": "polestar.com",
    "Porsche": "porsche.com", "Mitsubishi": "mitsubishicars.com", "Mini": "miniusa.com",
}

cars = []

def add(make, model, year, bodyType, segment, priceMin, priceMax, seats, cargoCuFt,
        mpgCity=None, mpgHwy=None, mpgCombined=None, fuelType="gas", evRangeMi=None,
        drivetrain="FWD", awdAvailable=False, zeroToSixty=8.5, horsepower=0,
        towingLbs=0, groundClearanceIn=6.0, offroad=False, safetyRating=4.5,
        techScore=3.5, comfortScore=3.5, features=None, useCases=None, notes=""):
    rel = BRAND_RELIABILITY.get(make, 3.5)
    car = {
        "id": f"{make.lower().replace(' ', '-')}-{model.lower().replace(' ', '-').replace('/', '-')}",
        "make": make, "model": model, "year": year,
        "bodyType": bodyType, "segment": segment,
        "priceMin": priceMin, "priceMax": priceMax,
        "seats": seats, "cargoCuFt": cargoCuFt,
        "mpgCity": mpgCity, "mpgHwy": mpgHwy, "mpgCombined": mpgCombined,
        "fuelType": fuelType, "evRangeMi": evRangeMi,
        "drivetrain": drivetrain, "awdAvailable": awdAvailable or drivetrain in ("AWD", "4WD"),
        "zeroToSixty": zeroToSixty, "horsepower": horsepower,
        "towingLbs": towingLbs, "groundClearanceIn": groundClearanceIn, "offroad": offroad,
        "safetyRating": safetyRating, "reliabilityScore": rel,
        "techScore": techScore, "comfortScore": comfortScore,
        "features": features or [],
        "useCases": useCases or [],
        "officialSite": BRAND_SITE.get(make, ""),
        "notes": notes,
    }
    cars.append(car)

